 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: rgba(14, 21, 40, 0.92);
       --panel-border: rgba(148, 163, 184, 0.22);
       --text: #e5eefb;
       --muted: #9fb0cf;
       --accent: #7dd3fc;
       --accent-strong: #38bdf8;
       --field: #111a31;
