       --success: #86efac;
       --success-bg: rgba(20, 83, 45, 0.28);
       --shadow: 0 24px 60px rgba(2, 6, 23, 0.5);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Arial, Helvetica, sans-serif;
