 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content" tabindex="-1">
     <section class="support-card" aria-labelledby="support-title">
       <p class="eyebrow">Support</p>
       <h1 id="support-title">Get help from our team</h1>
       <p class="intro">Tell us how to reach you and a support specialist will follow up as soon as possible.</p>

       <form id="support-form" novalidate>
         <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required fields</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-errormessage="full-name-error"
           >
           <p id="full-name-error" class="field-error" hidden>Error: Enter your full name.</p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
           <input
             id="email-address"
             name="email"
             type="email"
             autocomplete="email"
             inputmode="email"
             required
             aria-errormessage="email-address-error"
           >
           <p id="email-address-error" class="field-error" hidden>Error: Enter a valid email address such as name@example.com.</p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-number-hint"
             aria-errormessage="phone-number-error"
           >
           <p id="phone-number-hint" class="field-hint">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
           <p id="phone-number-error" class="field-error" hidden>Error: Enter a phone number in a valid format, such as (555) 123-4567.</p>
         </div>

         <div class="actions">
           <button type="submit">Send support request</button>
         </div>

         <p id="form-status" class="status-message" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const statusMessage = document.getElementById('form-status');
     const fieldConfig = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           return value.trim().length > 0 ? '' : 'Error: Enter your full name.';
         }
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate(value, input) {
           if (!value.trim()) {
             return 'Error: Enter your email address.';
           }

           return input.validity.typeMismatch ? 'Error: Enter a valid email address such as name@example.com.' : '';
         }
       },
       {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate(value) {
           if (!value.trim()) {
             return '';
           }

           const phonePattern = /^\+?[0-9().\s-]{7,20}$/;
           const digitsOnly = value.replace(/\D/g, '');
           return phonePattern.test(value) && digitsOnly.length >= 7
             ? ''
             : 'Error: Enter a phone number in a valid format, such as (555) 123-4567.';
         }
       }
     ];

     let hasSubmitted = false;

     function setFieldState(config) {
       const message = config.validate(config.input.value, config.input);
       const isValid = message === '';

       if (isValid) {
         config.input.removeAttribute('aria-invalid');
       } else {
         config.input.setAttribute('aria-invalid', 'true');
       }

       config.error.textContent = message || config.error.textContent;
       config.error.hidden = isValid;
       return isValid;
     }

     fieldConfig.forEach((config) => {
       config.input.addEventListener('blur', () => {
         setFieldState(config);
       });

       config.input.addEventListener('input', () => {
         if (hasSubmitted || config.input.getAttribute('aria-invalid') === 'true') {
           setFieldState(config);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       hasSubmitted = true;
       statusMessage.textContent = '';
       statusMessage.classList.remove('is-success');

       const firstInvalid = fieldConfig.find((config) => !setFieldState(config));

       if (firstInvalid) {
         firstInvalid.input.focus();
         return;
       }

       statusMessage.textContent = 'Your support request is ready to send.';
       statusMessage.classList.add('is-success');
       form.reset();
       hasSubmitted = false;

       fieldConfig.forEach((config) => {
         config.input.removeAttribute('aria-invalid');
         config.error.hidden = true;
       });
     });
   </script>
